let seed = `CREATE TABLE customers(id INTEGER PRIMARY KEY,name TEXT,city TEXT,joined_at TEXT);CREATE TABLE products(id INTEGER PRIMARY KEY,name TEXT,category TEXT,price REAL);CREATE TABLE orders(id INTEGER PRIMARY KEY,customer_id INTEGER,product_id INTEGER,quantity INTEGER,status TEXT,ordered_at TEXT);
INSERT INTO customers VALUES(1,'Alice','Chicago','2024-01-10'),(2,'Ben','Austin','2024-02-12'),(3,'Cara','Seattle','2024-03-05'),(4,'Dev','Chicago','2024-04-20'),(5,'Elena',NULL,'2024-05-01'),(6,'Finn','Austin','2024-06-15'),(7,'Grace','Seattle','2024-07-07'),(8,'Hugo','Boston','2024-08-09');
INSERT INTO products VALUES(1,'Notebook','Stationery',12),(2,'Desk lamp','Home',45),(3,'Keyboard','Tech',80),(4,'Pen set','Stationery',8),(5,'Headphones','Tech',120),(6,'Plant pot','Home',20);
INSERT INTO orders VALUES(101,1,1,2,'paid','2025-01-01'),(102,2,3,1,'paid','2025-01-02'),(103,1,2,1,'paid','2025-01-05'),(104,3,5,2,'pending','2025-01-08'),(105,4,4,5,'paid','2025-02-01'),(106,2,5,1,'cancelled','2025-02-03'),(107,5,6,3,'paid','2025-02-10'),(108,6,1,4,'paid','2025-02-15'),(109,3,3,1,'paid','2025-03-01'),(110,1,5,1,'paid','2025-03-03'),(111,7,2,2,'pending','2025-03-08'),(112,4,3,2,'paid','2025-03-15');`;
const groups=['Foundations','Working with rows','Summaries','Relationships','Advanced SQL'];
const lessons=[];
function lesson(title,group,concept,example,tasks,hints,trap){lessons.push({id:lessons.length,title,group,concept,example,tasks:tasks.map(([prompt,answer,ordered=false])=>({prompt,answer,ordered})),hints,trap});}
lesson('Meet your first SELECT',0,'A table is a collection of rows and named columns. SELECT chooses the columns you want to see; FROM names the table. A query reads data without changing it.','SELECT name, city\nFROM customers;',[['Show the name and city of every customer.','SELECT name, city FROM customers'],['Show the name and price of every product.','SELECT name, price FROM products']],['Name the two columns after SELECT, separated by a comma.','Use FROM customers for the first challenge; FROM products for the second.'],'SELECT * includes extra columns. Return only the columns the task asks for.');
lesson('Aliases & calculated columns',0,'AS gives an output column a readable name. You can calculate values for each row with arithmetic. The original table stays unchanged.','SELECT name, price * 2 AS double_price\nFROM products;',[['Return name and price * 2 as double_price for every product.','SELECT name, price*2 AS double_price FROM products'],['Return id and quantity * 10 as units_times_ten for every order.','SELECT id, quantity*10 AS units_times_ten FROM orders']],['Use multiplication in SELECT.','Use AS to name the calculated column exactly as requested.'],'A quoted number is text. Use a numeric expression for arithmetic.');
lesson('Unique values with DISTINCT',0,'DISTINCT removes duplicate output rows. It applies to the whole set of selected columns, not just the first column. NULL is kept once.','SELECT DISTINCT city\nFROM customers;',[['Show each distinct customer city, including NULL.','SELECT DISTINCT city FROM customers'],['Show each distinct product category.','SELECT DISTINCT category FROM products']],['Add DISTINCT directly after SELECT.','Select just the column whose unique values you want.'],'Adding id makes every row unique, so it defeats this task.');
lesson('Filter with WHERE',1,'WHERE keeps rows for which a condition is true. Text values need single quotes; column names do not. Rows whose comparison evaluates to NULL are not kept.','SELECT name, city FROM customers\nWHERE city = \'Chicago\';',[['Show name and city for customers in Chicago.','SELECT name,city FROM customers WHERE city=\'Chicago\''],['Show name and city for customers in Austin.','SELECT name,city FROM customers WHERE city=\'Austin\'']],['Use WHERE city = a quoted city.','Return only name and city.'],'SQL uses = for equality. City names are string values, so quote them.');
lesson('Comparisons & ranges',1,'Use >, >=, < and <= to compare values. BETWEEN includes both endpoints. Decide whether the task includes the boundary before choosing an operator.','SELECT name, price FROM products\nWHERE price >= 45;',[['Show name and price for products priced at least 45.','SELECT name,price FROM products WHERE price>=45'],['Show name and price for products priced between 12 and 80 inclusive.','SELECT name,price FROM products WHERE price BETWEEN 12 AND 80']],['At least means >=. BETWEEN is inclusive.','Compare the price column to numeric values.'],'Using > instead of >= drops the boundary row.');
lesson('Combine conditions',1,'AND requires both conditions. OR requires either. AND binds more tightly than OR, so parentheses make mixed conditions explicit.','SELECT name, price FROM products\nWHERE category = \'Tech\' AND price < 100;',[['Show name and price for Tech products costing less than 100.','SELECT name,price FROM products WHERE category=\'Tech\' AND price<100'],['Show name and price for Home or Stationery products costing at least 12.','SELECT name,price FROM products WHERE (category=\'Home\' OR category=\'Stationery\') AND price>=12']],['Use AND when both conditions must be true.','Group the two categories with parentheses before applying the price condition.'],'Without parentheses, a price filter may apply to only one side of OR.');
lesson('Lists & text patterns',1,'IN matches any member of a list. LIKE matches text patterns: % means any number of characters and _ means one character. SQLite LIKE is case-insensitive for ASCII by default.','SELECT name FROM customers\nWHERE name LIKE \'A%\';',[['Show name for customers whose name starts with A.','SELECT name FROM customers WHERE name LIKE \'A%\''],['Show name and city for customers in Austin or Seattle.','SELECT name,city FROM customers WHERE city IN (\'Austin\',\'Seattle\')']],['A prefix pattern ends with %.','Use IN with a parenthesized list of quoted cities.'],'An equality comparison with A% looks for a literal percent sign.');
lesson('Understand NULL',1,'NULL means missing or unknown. NULL = NULL is unknown, not true. Use IS NULL and IS NOT NULL. COALESCE returns the first non-NULL argument.','SELECT name, COALESCE(city, \'Unknown\') AS city\nFROM customers;',[['Show name for customers whose city is missing.','SELECT name FROM customers WHERE city IS NULL'],['Return name and city, replacing missing city with Unknown (alias the column city).','SELECT name,COALESCE(city,\'Unknown\') AS city FROM customers']],['Do not use = NULL.','Use IS NULL to find missing values, or COALESCE to replace them.'],'NULL is not the string \'NULL\', and it is not an empty string.');
lesson('Sort & limit',1,'ORDER BY sorts the output; ASC is ascending and DESC descending. LIMIT keeps a number of rows after sorting. Use a secondary key when ties need deterministic ordering.','SELECT name, price FROM products\nORDER BY price DESC, name ASC LIMIT 3;',[['Show name and price of the 3 most expensive products, highest price first.','SELECT name,price FROM products ORDER BY price DESC LIMIT 3',true],['Show name and price of the 2 cheapest products, lowest price first.','SELECT name,price FROM products ORDER BY price ASC LIMIT 2',true]],['Sort by price, then use LIMIT.','Most expensive needs DESC; cheapest needs ASC.'],'LIMIT without ORDER BY does not promise which rows you get.');
lesson('COUNT, SUM & AVG',2,'Aggregate functions collapse rows into a summary. COUNT(*) counts rows; COUNT(column) excludes NULL. SUM adds numeric values; AVG finds their mean.','SELECT COUNT(*) AS customer_count\nFROM customers;',[['Return the number of customers as customer_count.','SELECT COUNT(*) AS customer_count FROM customers'],['Return total order quantity as total_units.','SELECT SUM(quantity) AS total_units FROM orders']],['An aggregate query without GROUP BY returns one summary row.','Use COUNT(*) for rows or SUM(quantity) for units.'],'COUNT(city) excludes Elena because her city is NULL.');
lesson('Group into summaries',2,'GROUP BY forms one group for each key. Aggregates then summarize each group. Select grouping columns and aggregates to avoid ambiguous output.','SELECT category, COUNT(*) AS product_count\nFROM products GROUP BY category;',[['Show category and product_count for each product category.','SELECT category,COUNT(*) AS product_count FROM products GROUP BY category'],['Show status and total_units (sum of quantity) for each order status.','SELECT status,SUM(quantity) AS total_units FROM orders GROUP BY status']],['Put the grouping key after GROUP BY.','Use COUNT(*) or SUM(quantity) for the summary column.'],'Selecting an ungrouped name in SQLite can return an arbitrary member of the group.');
lesson('Filter groups with HAVING',2,'WHERE filters rows before grouping. HAVING filters groups after aggregation. Think rows → groups → group filter → output.','SELECT customer_id, COUNT(*) AS order_count\nFROM orders GROUP BY customer_id\nHAVING COUNT(*) >= 2;',[['Show customer_id and order_count for customers with at least 2 orders.','SELECT customer_id,COUNT(*) AS order_count FROM orders GROUP BY customer_id HAVING COUNT(*)>=2'],['Show customer_id and total_units for customers with total quantity greater than 3.','SELECT customer_id,SUM(quantity) AS total_units FROM orders GROUP BY customer_id HAVING SUM(quantity)>3']],['Filter the aggregate in HAVING.','The aggregate expression must match the summary you are testing.'],'WHERE cannot filter an aggregate computed by the same query block.');
lesson('Make decisions with CASE',2,'CASE creates a value based on conditions. SQL checks WHEN branches in order and uses the first match. ELSE covers remaining rows.','SELECT name, CASE WHEN price >= 80\nTHEN \'Premium\' ELSE \'Standard\' END AS tier\nFROM products;',[['Show name and tier: Premium if price >= 80, otherwise Standard.','SELECT name,CASE WHEN price>=80 THEN \'Premium\' ELSE \'Standard\' END AS tier FROM products'],['Show id and is_paid: 1 for paid orders, otherwise 0.','SELECT id,CASE WHEN status=\'paid\' THEN 1 ELSE 0 END AS is_paid FROM orders']],['CASE WHEN condition THEN value ELSE value END.','Add AS tier or AS is_paid.'],'Without ELSE, unmatched rows become NULL.');
lesson('Conditional aggregation',2,'Put CASE inside SUM to count or add only matching rows. ELSE 0 prevents nonmatching rows from contributing. This can produce multiple summaries in one scan.','SELECT SUM(CASE WHEN status = \'paid\'\nTHEN 1 ELSE 0 END) AS paid_count FROM orders;',[['Return paid_count: the number of paid orders.','SELECT SUM(CASE WHEN status=\'paid\' THEN 1 ELSE 0 END) AS paid_count FROM orders'],['Return paid_units: the sum of quantity for paid orders.','SELECT SUM(CASE WHEN status=\'paid\' THEN quantity ELSE 0 END) AS paid_units FROM orders']],['Wrap CASE in SUM.','Return 1 to count a row; return quantity to sum units.'],'COUNT(CASE ... ELSE 0 END) counts zero values too because they are not NULL.');
lesson('Connect tables with JOIN',3,'INNER JOIN pairs rows whose join condition matches. Aliases keep column references short. One customer can match several orders, so joins can increase row counts.','SELECT o.id, c.name FROM orders o\nJOIN customers c ON c.id = o.customer_id;',[['Return every order id and its customer name (columns id, name).','SELECT o.id,c.name FROM orders o JOIN customers c ON c.id=o.customer_id'],['Return every order id and its product name (columns id, name).','SELECT o.id,p.name FROM orders o JOIN products p ON p.id=o.product_id']],['Match the foreign key in orders to the other table\'s id.','Use table aliases to distinguish the two id columns.'],'Joining without the correct ON condition can multiply unrelated rows.');
lesson('Keep unmatched rows',3,'LEFT JOIN keeps every row from the left table. When no match exists, right-side columns are NULL. A right-table filter in WHERE may remove those unmatched rows.','SELECT c.name, COUNT(o.id) AS order_count\nFROM customers c LEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id, c.name;',[['Show every customer name and order_count, including customers with zero orders.','SELECT c.name,COUNT(o.id) AS order_count FROM customers c LEFT JOIN orders o ON o.customer_id=c.id GROUP BY c.id,c.name'],['Show name for customers with no orders.','SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE o.id IS NULL']],['Customers must be on the left side.','COUNT(o.id) ignores NULL; COUNT(*) would count the unmatched placeholder row.'],'Using INNER JOIN loses Hugo, who has no orders.');
lesson('Revenue across tables',3,'Join transaction rows to product prices, multiply price by quantity, then aggregate at the desired grain. Filter status before computing paid revenue.','SELECT c.name, SUM(o.quantity * p.price) AS revenue\nFROM orders o JOIN customers c ON c.id=o.customer_id\nJOIN products p ON p.id=o.product_id\nWHERE o.status=\'paid\' GROUP BY c.id,c.name;',[['Show customer name and paid revenue (alias revenue), only customers with paid orders.','SELECT c.name,SUM(o.quantity*p.price) AS revenue FROM orders o JOIN customers c ON c.id=o.customer_id JOIN products p ON p.id=o.product_id WHERE o.status=\'paid\' GROUP BY c.id,c.name'],['Show category and paid revenue (alias revenue) for each category with paid orders.','SELECT p.category,SUM(o.quantity*p.price) AS revenue FROM orders o JOIN products p ON p.id=o.product_id WHERE o.status=\'paid\' GROUP BY p.category']],['Revenue per order is quantity * price.','Join products on product_id and filter to paid before grouping.'],'Summing price without quantity undercounts multi-unit orders.');
lesson('Subqueries',3,'A subquery is a query inside another query. A scalar subquery produces one value, which can be used in a comparison. Parentheses separate the inner query.','SELECT name, price FROM products\nWHERE price > (SELECT AVG(price) FROM products);',[['Show name and price of products above the average product price.','SELECT name,price FROM products WHERE price>(SELECT AVG(price) FROM products)'],['Show id and quantity for orders whose quantity is above the average order quantity.','SELECT id,quantity FROM orders WHERE quantity>(SELECT AVG(quantity) FROM orders)']],['Calculate the average with an inner SELECT.','Use > followed by the parenthesized subquery.'],'The inner average summarizes the entire table; it is not a per-row calculation.');
lesson('Ask whether a row exists',3,'EXISTS is true when its subquery returns at least one row. A correlated subquery refers to the outer row. NOT EXISTS is useful for finding missing relationships.','SELECT c.name FROM customers c\nWHERE EXISTS (SELECT 1 FROM orders o\nWHERE o.customer_id=c.id AND o.status=\'paid\');',[['Show name of customers who have at least one paid order.','SELECT c.name FROM customers c WHERE EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status=\'paid\')'],['Show name of customers who have no paid orders.','SELECT c.name FROM customers c WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status=\'paid\')']],['Correlate customer_id to the outer customer id.','Use EXISTS for at least one, NOT EXISTS for none.'],'A join may duplicate customer names; EXISTS preserves one outer row.');
lesson('Combine sets with UNION',3,'UNION stacks compatible query outputs and removes duplicate rows. UNION ALL retains duplicates. Both sides need the same number of columns in matching positions.','SELECT city FROM customers WHERE city=\'Chicago\'\nUNION SELECT city FROM customers WHERE city=\'Austin\';',[['Return distinct city values from Chicago customers and Austin customers using UNION.','SELECT city FROM customers WHERE city=\'Chicago\' UNION SELECT city FROM customers WHERE city=\'Austin\''],['Stack name from customers and name from products, keeping duplicates.','SELECT name FROM customers UNION ALL SELECT name FROM products']],['Stack SELECT statements using UNION or UNION ALL.','The output column name comes from the first SELECT.'],'UNION combines rows vertically; JOIN combines columns horizontally.');
lesson('Readable queries with CTEs',4,'WITH names a temporary query result for this statement. Common table expressions help you separate a complicated question into understandable stages. They do not create permanent tables.','WITH totals AS (\n SELECT customer_id, SUM(quantity) AS units\n FROM orders GROUP BY customer_id\n) SELECT customer_id, units FROM totals WHERE units > 3;',[['Use a CTE to return customer_id and units for customers whose total quantity exceeds 3.','WITH totals AS(SELECT customer_id,SUM(quantity) AS units FROM orders GROUP BY customer_id) SELECT customer_id,units FROM totals WHERE units>3'],['Use a CTE to return category and avg_price for categories with average price greater than 30.','WITH averages AS(SELECT category,AVG(price) AS avg_price FROM products GROUP BY category) SELECT category,avg_price FROM averages WHERE avg_price>30']],['Define the intermediate result with WITH name AS (...).','The outer query filters the named result.'],'A CTE exists only for the statement that follows it.');
lesson('Window functions: ROW_NUMBER',4,'Window functions calculate across related rows while keeping each row visible. ROW_NUMBER assigns 1, 2, 3 within a partition using its ORDER BY. Include a tie-breaker for repeatable results.','SELECT id, customer_id, ROW_NUMBER() OVER(\n PARTITION BY customer_id ORDER BY ordered_at, id\n) AS order_number FROM orders;',[['Return id, customer_id and order_number: number each customer\'s orders by ordered_at then id.','SELECT id,customer_id,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY ordered_at,id) AS order_number FROM orders'],['Return name, category and price_rank: number products within category by price descending then id.','SELECT name,category,ROW_NUMBER() OVER(PARTITION BY category ORDER BY price DESC,id) AS price_rank FROM products']],['PARTITION BY restarts numbering per group.','Put ORDER BY inside OVER to control numbering.'],'The window ORDER BY controls calculation, not the final display order.');
lesson('RANK & DENSE_RANK',4,'RANK gives ties the same rank, then leaves a gap. DENSE_RANK gives ties the same rank without gaps. ROW_NUMBER always assigns distinct numbers.','SELECT customer_id, COUNT(*) AS order_count,\nDENSE_RANK() OVER(ORDER BY COUNT(*) DESC) AS rank\nFROM orders GROUP BY customer_id;',[['Show customer_id, order_count and rank using DENSE_RANK by order_count descending.','SELECT customer_id,COUNT(*) AS order_count,DENSE_RANK() OVER(ORDER BY COUNT(*) DESC) AS rank FROM orders GROUP BY customer_id'],['Show customer_id, order_count and rank using RANK by order_count descending.','SELECT customer_id,COUNT(*) AS order_count,RANK() OVER(ORDER BY COUNT(*) DESC) AS rank FROM orders GROUP BY customer_id']],['Aggregate counts first; rank those grouped rows.','Do not put customer_id in the window sort: that would break count ties.'],'Ties exist in this dataset, so RANK and DENSE_RANK produce different outputs.');
lesson('Running totals',4,'SUM as a window function keeps each row and accumulates values over a frame. ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW means all earlier rows plus this row.','SELECT id, quantity, SUM(quantity) OVER(\n ORDER BY ordered_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n) AS running_units FROM orders;',[['Show id, quantity and running_units: cumulative quantity ordered by ordered_at then id.','SELECT id,quantity,SUM(quantity) OVER(ORDER BY ordered_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_units FROM orders'],['Show id, customer_id and running_units: cumulative quantity per customer ordered by ordered_at then id.','SELECT id,customer_id,SUM(quantity) OVER(PARTITION BY customer_id ORDER BY ordered_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_units FROM orders']],['Use SUM(quantity) OVER (...).','The second task needs PARTITION BY customer_id.'],'Specify a ROWS frame to avoid a default RANGE frame grouping equal sort values.');
lesson('Compare rows with LAG',4,'LAG reads a value from a previous row within a window. The first row has no predecessor, so its result is NULL unless you supply a default.','SELECT id, customer_id, LAG(quantity) OVER(\n PARTITION BY customer_id ORDER BY ordered_at,id\n) AS previous_quantity FROM orders;',[['Show id, customer_id and previous_quantity for the previous order of each customer, ordered by ordered_at then id.','SELECT id,customer_id,LAG(quantity) OVER(PARTITION BY customer_id ORDER BY ordered_at,id) AS previous_quantity FROM orders'],['Show id, quantity and change: current quantity minus previous quantity across all orders, ordered by ordered_at then id.','SELECT id,quantity,quantity-LAG(quantity) OVER(ORDER BY ordered_at,id) AS change FROM orders']],['The argument of LAG is the value you want from the previous row.','Subtract LAG(quantity) from quantity to calculate change.'],'LAG uses the window ordering; it is not the previous row in storage.');
lesson('Latest row per group',4,'Use a CTE with ROW_NUMBER sorted newest-first, then filter to row number 1. A window result cannot be filtered by WHERE in the same query block.','WITH ranked AS (\n SELECT *, ROW_NUMBER() OVER(PARTITION BY customer_id\n ORDER BY ordered_at DESC,id DESC) AS rn FROM orders\n) SELECT id,customer_id,ordered_at FROM ranked WHERE rn=1;',[['Return id, customer_id and ordered_at for the latest order per customer; break date ties by highest id.','WITH ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY ordered_at DESC,id DESC) AS rn FROM orders) SELECT id,customer_id,ordered_at FROM ranked WHERE rn=1'],['Return name, category and price for the most expensive product per category; break price ties by lowest id.','WITH ranked AS(SELECT *,ROW_NUMBER() OVER(PARTITION BY category ORDER BY price DESC,id) AS rn FROM products) SELECT name,category,price FROM ranked WHERE rn=1']],['Number rows inside a CTE, then filter outside it.','Keep rn = 1 in the outer WHERE.'],'MAX(date) plus an unrelated id does not reliably select the entire latest row.');
lesson('Dates & monthly analysis',4,'SQLite stores these dates as ISO text. strftime formats dates: %Y-%m extracts a year and month. Group by that expression to build a monthly summary. Other SQL dialects use different date functions.','SELECT strftime(\'%Y-%m\', ordered_at) AS month,\nCOUNT(*) AS order_count FROM orders GROUP BY month;',[['Return month (YYYY-MM) and order_count for all orders by month.','SELECT strftime(\'%Y-%m\',ordered_at) AS month,COUNT(*) AS order_count FROM orders GROUP BY month'],['Return month (YYYY-MM) and paid_units for paid orders by month.','SELECT strftime(\'%Y-%m\',ordered_at) AS month,SUM(quantity) AS paid_units FROM orders WHERE status=\'paid\' GROUP BY month']],['Use strftime with %Y-%m.','Filter paid rows before grouping for the second task.'],'Grouping only by month number mixes years.');
lesson('Recursive CTEs',4,'A recursive CTE has an anchor row and a recursive step joined by UNION ALL. The step uses the previous result until its stopping condition is false. Always include a termination condition.','WITH RECURSIVE numbers(n) AS (\n SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<5\n) SELECT n FROM numbers;',[['Use a recursive CTE to return n with integers 1 through 5.','WITH RECURSIVE numbers(n) AS(SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<5) SELECT n FROM numbers'],['Use a recursive CTE to return n with integers 1 through 10.','WITH RECURSIVE numbers(n) AS(SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<10) SELECT n FROM numbers']],['Anchor with SELECT 1.','Increment n and stop at the requested upper bound.'],'An unbounded recursive query is interrupted by the app time limit.');
lesson('Query plans & indexes',4,'An index can help SQLite find or order rows efficiently. EXPLAIN QUERY PLAN shows SCAN versus SEARCH and index use. Indexes cost storage and slow writes; the optimizer may still scan a tiny table.','EXPLAIN QUERY PLAN\nSELECT name FROM customers WHERE city=\'Chicago\';',[['Show name for Chicago customers. Run the reference with Explain mode to inspect the plan.','SELECT name FROM customers WHERE city=\'Chicago\''],['Show id and quantity for paid orders. Inspect its plan with Explain mode.','SELECT id,quantity FROM orders WHERE status=\'paid\'']],['Write the SELECT normally; choose Explain for its plan.','Plan output is informative; submit the normal query to check the answer.'],'A full scan is not automatically bad; table size and selectivity matter.');
lesson('Capstone: customer insights',4,'Combine filtering, joins, aggregation and ranking to answer a business question. First compute each customer\'s paid revenue, then rank those customer totals. Write one stage at a time.','WITH revenue AS (\n SELECT c.name,SUM(o.quantity*p.price) AS paid_revenue\n FROM customers c JOIN orders o ON o.customer_id=c.id\n JOIN products p ON p.id=o.product_id\n WHERE o.status=\'paid\' GROUP BY c.id,c.name\n) SELECT name,paid_revenue,DENSE_RANK() OVER(ORDER BY paid_revenue DESC) AS revenue_rank FROM revenue;',[['Show name, paid_revenue and revenue_rank for customers with paid orders. Use DENSE_RANK, highest revenue first in the rank calculation.','WITH revenue AS(SELECT c.name,SUM(o.quantity*p.price) AS paid_revenue FROM customers c JOIN orders o ON o.customer_id=c.id JOIN products p ON p.id=o.product_id WHERE o.status=\'paid\' GROUP BY c.id,c.name) SELECT name,paid_revenue,DENSE_RANK() OVER(ORDER BY paid_revenue DESC) AS revenue_rank FROM revenue'],['Show category, paid_revenue and revenue_rank for product categories with paid orders. Use DENSE_RANK by revenue descending.','WITH revenue AS(SELECT p.category,SUM(o.quantity*p.price) AS paid_revenue FROM orders o JOIN products p ON p.id=o.product_id WHERE o.status=\'paid\' GROUP BY p.category) SELECT category,paid_revenue,DENSE_RANK() OVER(ORDER BY paid_revenue DESC) AS revenue_rank FROM revenue']],['Compute paid revenue in a grouped CTE.','Rank the revenue column in the outer query.'],'Rank customer totals, not individual order amounts.');
const schemas={customers:['id INTEGER · primary key','name TEXT','city TEXT · nullable','joined_at TEXT · ISO date'],products:['id INTEGER · primary key','name TEXT','category TEXT','price REAL'],orders:['id INTEGER · primary key','customer_id INTEGER → customers.id','product_id INTEGER → products.id','quantity INTEGER','status TEXT','ordered_at TEXT · ISO date']};
